using System;
class VehicleDamageTests {
 static int checks;
 static void Check(bool ok,string text){checks++;if(!ok){Console.WriteLine("FAIL "+text);Environment.Exit(1);}}
 static void Invalid(Action action,string text){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}Check(rejected,text);}
 static EconomyLedger Ledger(int cash=1000,bool oneDay=true,double seconds=1200){return new EconomyLedger(new PrototypeSettings{startCash=cash,oneDay=oneDay,days=3,target=100000,daySeconds=(float)seconds,parking=0,meal=3000,initialFuel=50});}
 static void Disable(VehicleDamage d){d.Impact(20);d.Advance(.8,false);d.Impact(20);}
 static void Main(){
  double[] speed={0,1.49999,1.5,2.99999,3,5.99999,6,9.99999,10,14.99999,15,100};int[] loss={0,0,2,2,6,6,15,15,30,30,50,50};
  for(int i=0;i<speed.Length;i++){var d=new VehicleDamage();Check(d.Durability==100&&!d.Disabled&&d.RepairBayId=="","fresh condition");Check(d.Impact(speed[i])==loss[i]&&d.Durability==100-loss[i],"tier boundary "+speed[i]);}
  var damage=new VehicleDamage();Check(damage.Impact(3)==6&&damage.Impact(5)==0&&damage.Impact(10)==24&&damage.Durability==70,"incident charges only stronger increment");
  for(int i=0;i<100;i++){damage.Advance(.1,true);Check(damage.Impact(10)==0,"continuous wall push no repeated loss");}
  damage.Advance(.79,false);Check(damage.Impact(10)==0,"brief separation same incident");damage.Advance(.4,false);damage.Advance(.4,false);Check(damage.Impact(10)==30,"all contacts absent .8 resets incident");
  damage.Advance(.4,false);damage.Advance(10,true);damage.Advance(.4,false);Check(damage.Impact(10)==0,"one continuing contact cancels detach timer");
  damage.Advance(.8,false);Check(damage.Impact(20)==40&&damage.Durability==0&&damage.Disabled,"actual loss clamped to remaining durability");Check(damage.Impact(30)==0,"disabled cannot go below zero");
  var grace=new VehicleDamage();grace.Impact(6);grace.Suppress(2);grace.Suppress(1);Check(grace.Durability==85&&grace.Impact(20)==0,"suppression no heal or shorten");grace.Advance(1.9,false);Check(grace.Impact(20)==0,"grace remains");grace.Advance(.1,false);Check(grace.Impact(20)==50,"grace expires");
  var saved=new VehicleDamage();saved.Impact(3);saved.Advance(.3,false);saved.Suppress(.5);var snapshot=saved.Snapshot();var copy=VehicleDamage.Restore(snapshot);snapshot.durability=1;Check(copy.Durability==94&&saved.Durability==94,"snapshot independent copy");copy.Advance(.5,false);Check(copy.Impact(10)==30,"detach and grace checkpoint resume");
  Check(VehicleDamage.Restore(null).Durability==100&&VehicleCare.Restore(new VehicleCareSnapshot()).Damage.Durability==100,"legacy snapshot begins undamaged");
  Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot());},"current damage payload requires explicit version");
  foreach(int n in new[]{-1,101})Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,durability=n});},"invalid durability");
  foreach(double n in new[]{double.NaN,double.PositiveInfinity,-1}){Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,graceSeconds=n});},"invalid grace");Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,detachedSeconds=n});},"invalid detach");}
  Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,incidentTier=7});},"invalid tier");Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,detachedSeconds=.8,incidentTier=6});},"expired incident rejected");Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,repairBayId="bay"});},"bay cannot contain running vehicle");
  Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,durability=100,incidentTier=6});},"incident cannot have charged more than total damage");
  Invalid(delegate{VehicleDamage.Restore(new VehicleDamageSnapshot{version=1,durability=0,repairBayId=" "});},"blank tow bay rejected");
  var same=VehicleDamage.Restore(saved.Snapshot());same.Advance(.5,true);Check(same.Impact(3)==0&&same.Impact(10)==24,"saved contact tier prevents replay loss");
  Check(VehicleCare.Restore(new VehicleCareSnapshot{damageVersion=0,damage=new VehicleDamageSnapshot{version=1,durability=0}}).Damage.Durability==100,"legacy nested phantom ignored by version marker");
  Check(new VehicleCare().Snapshot().damageVersion==1,"new snapshot explicitly marks damage present");
  Invalid(delegate{VehicleCare.Restore(new VehicleCareSnapshot{damageVersion=1,damage=null});},"current damage must be present");
  foreach(int version in new[]{-1,2})Invalid(delegate{VehicleCare.Restore(new VehicleCareSnapshot{damageVersion=version});},"unknown damage version rejected");
  var badInput=new VehicleDamage();foreach(double n in new[]{double.NaN,double.PositiveInfinity,-1}){Check(badInput.Impact(n)==0,"invalid impact ignored");badInput.Advance(n,false);badInput.Suppress(n);}Check(badInput.Durability==100,"invalid timing cannot change damage");
  var ledger=Ledger();ledger.Care.MarkVomit();ledger.Care.Soil("mud",20);ledger.Care.Damage.Impact(6);Check(ledger.RepairCost==3000&&ledger.RepairSeconds==17.5,"repair quote");double satiety=ledger.Driver.satiety;float fuel=ledger.Account.Fuel;
  Check(ledger.UseRepair("repair")&&ledger.Care.Damage.Durability==100,"repair restores durability");Check(ledger.Account.Cash==0&&ledger.Account.Debt==2000&&ledger.Account.Expense(1,"repair")==3000,"repair cash first remainder debt");Check(ledger.Elapsed==17.5&&ledger.Metrics.Capture().serviceSeconds==17.5&&ledger.Driver.satiety<satiety&&ledger.Account.Fuel==fuel,"repair engine off time condition metrics");Check(ledger.Care.VomitUnwashed&&ledger.Care.Cleanliness==80,"repair leaves dirt vomit intact");Check(!ledger.UseRepair("repair")&&!ledger.UseRepair("healthy"),"repair repeats and undamaged rejected");
  ledger.Care.Damage.Impact(6);Check(!ledger.UseRepair("repair")&&ledger.Care.Damage.Durability==85,"used id cannot heal new damage");Check(!ledger.UseTow("early","bay"),"tow only disabled");Disable(ledger.Care.Damage);ledger.Care.Damage.Advance(.8,false);ledger.Care.Damage.Impact(20);Check(!ledger.CanAccept,"disabled blocks acceptance");
  Check(!ledger.UseTow("", "bay")&&!ledger.UseTow("tow", ""),"tow valid identities only");double before=ledger.Elapsed;Check(ledger.UseTow("tow","bay-A")&&ledger.Care.Damage.Disabled&&ledger.Care.Damage.RepairBayId=="bay-A","tow marks bay without repair");Check(ledger.Account.Debt==5000&&ledger.Elapsed==before+30&&ledger.Account.Fuel==fuel,"tow price and engine off thirty seconds");Check(!ledger.UseTow("tow","bay-A")&&!ledger.UseTow("other","bay-B"),"tow replay and occupied marker no duplicate charge");
  var restored=EconomyLedger.RestoreCampaign(ledger.Snapshot(),ledger.Account.Snapshot());Check(restored.Care.Damage.RepairBayId=="bay-A"&&restored.Care.Damage.Durability==0&&!restored.UseTow("tow","bay-A"),"active checkpoint no repeat tow");Check(restored.UseRepair("repair-after-tow")&&restored.Care.Damage.RepairBayId==""&&restored.Care.Damage.Durability==100,"repair releases tow bay");
  restored.RequestClose();Check(restored.Settle()&&restored.Last.repair==23000&&restored.Last.tow==3000&&restored.Last.net==-26000,"settlement expenses exactly once");Check(restored.NextDay()&&restored.Care.Damage.Durability==100&&restored.Care.VomitUnwashed,"next day care independent");
  var carry=Ledger();Disable(carry.Care.Damage);carry.RequestClose();Check(carry.UseTow("close-tow","C")&&carry.UseRepair("close-repair"),"services allowed during closing");carry.Care.Damage.Impact(3);carry.Settle();var dayRestore=EconomyLedger.RestoreCampaign(carry.Snapshot(),carry.Account.Snapshot());Check(dayRestore.Last.repair==20000&&dayRestore.Last.tow==3000&&dayRestore.Last.net==carry.Last.net,"summary restore normalizes costs");Check(dayRestore.NextDay()&&dayRestore.Care.Damage.Durability==94,"next day never heals damage");dayRestore.Care.Damage.LeaveRepairBay();Check(dayRestore.Care.Damage.Durability==94,"leaving bay no heal");
  var crossing=Ledger(1000,false,10);crossing.Care.Damage.Impact(3);Check(crossing.UseRepair("budget")&&crossing.State==BusinessState.Closing&&crossing.Elapsed==13,"repair crosses campaign budget");Check(crossing.Settle()&&!crossing.UseRepair("summary")&&!crossing.UseTow("summary-tow","B"),"summary refuses services");
  var one=Ledger(1000,true,10);Disable(one.Care.Damage);Check(one.UseTow("budget-tow","B")&&one.Driver.fatigue==100&&one.Elapsed==30,"tow crosses one day budget and condition");
  var legacy=new EconomyLedger(new EconomySettings());legacy.Care.Damage.Impact(6);Check(!legacy.UseRepair("no-account")&&!legacy.UseTow("no-account","B"),"account required");
  var plainSnapshot=legacy.Snapshot();var plainRestored=EconomyLedger.Restore(plainSnapshot);Check(plainRestored.Care.Damage.Durability==85,"account-free checkpoint preserves damage");
  var fullCash=Ledger(100000);Disable(fullCash.Care.Damage);Check(fullCash.UseTow("tow-cash","D")&&fullCash.Account.Cash==97000&&fullCash.Account.Debt==0,"tow pays cash without debt when available");fullCash.Care.Damage.LeaveRepairBay();Check(!fullCash.UseTow("tow-cash","D")&&fullCash.Care.Damage.Disabled,"leaving bay cannot replay old tow identity");Check(fullCash.UseRepair("repair-cash")&&fullCash.Account.Cash==77000&&fullCash.Account.Debt==0,"full repair pays available cash");
  var nested=fullCash.Care.Snapshot();nested.damage.durability=1;Check(fullCash.Care.Damage.Durability==100,"nested snapshot copied");nested.damage.durability=-1;Invalid(delegate{VehicleCare.Restore(nested);},"care validates nested damage");
  Console.WriteLine("VehicleDamageTests PASS "+checks+" checks");
 }
}
